<script setup>
import { onMounted, ref } from "vue"; import { getKnowledgeDocuments, uploadKnowledgeDocument, deleteKnowledgeDocument, rebuildKnowledge } from "../../services/adminRepository";
const rows=ref([]),loading=ref(true),error=ref(""),busy=ref(false),toast=ref(""); async function load(){loading.value=true;try{rows.value=await getKnowledgeDocuments()}catch(e){error.value=e.response?.data?.detail||e.message||"加载失败"}finally{loading.value=false}} async function upload(e){const file=e.target.files?.[0];if(!file)return;busy.value=true;try{await uploadKnowledgeDocument(file);toast.value="文档已上传并进入解析";load()}catch(x){toast.value=x.response?.data?.detail||"上传失败"}finally{busy.value=false;e.target.value=""}} async function remove(row){if(!confirm(`确认删除“${row.title}”？`))return;try{await deleteKnowledgeDocument(row.document_id);toast.value="文档已删除";load()}catch(e){toast.value=e.response?.data?.detail||"删除失败"}} async function rebuild(){busy.value=true;try{await rebuildKnowledge();toast.value="索引已重建";load()}catch(e){toast.value=e.response?.data?.detail||"重建失败"}finally{busy.value=false}} onMounted(load);
</script>
<template><main class="portal-page admin-portal page-enter"><div v-if="toast" class="portal-toast">{{toast}}</div><div class="portal-heading"><div><span class="portal-kicker">内容治理</span><h1>知识库管理</h1><p>文档解析、分块与 BM25 索引状态均来自后端真实数据。</p></div><div><label class="primary-button">{{busy?'处理中…':'上传文档'}}<input hidden type="file" accept=".md,.txt,.pdf,.docx" @change="upload" /></label><button class="secondary-button" :disabled="busy" @click="rebuild">重建索引</button></div></div><div v-if="loading" class="portal-loading"><i v-for="n in 4" :key="n"></i></div><div v-else-if="error" class="portal-error">{{error}} <button @click="load">重试</button></div><section v-else class="portal-panel account-table"><div class="account-head"><span>文档</span><span>格式</span><span>大小</span><span>分块</span><span>导入时间</span><span>操作</span></div><article v-for="row in rows" :key="row.document_id" class="account-row"><div><strong>{{row.title}}</strong><small>{{row.original_filename||"—"}}</small></div><span>{{row.file_ext||"—"}}</span><span>{{row.file_size?`${Math.round(row.file_size/1024)} KB`:"—"}}</span><span>{{row.chunk_count}}</span><span>{{row.imported_at||"—"}}</span><button @click="remove(row)">删除</button></article><div v-if="!rows.length" class="portal-empty">知识库暂无文档</div></section></main></template>
